def compute(vars):
    current = vars["v1"]
    prior = vars["v2"]

    if prior == 0:
        return None

    change_ratio = (current - prior) / prior * 100

    return {
        "value": change_ratio,
        "trace": {
            "current_value": current,
            "prior_value": prior,
            "absolute_change": current - prior,
            "change_ratio_percent": change_ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percent"
            }
        }
    }
